children.content:
terraform {
  required_version = ">= 1.6.0"
  required_providers {
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4.0"
    }
  }
}

provider "local" {}

resource "local_file" "welcome" {
  filename = "${path.module}/trak_infra.txt"
  content  = "Welcome to Trak Terraform Workspace! Infrastructure provisioned successfully.\n"
}

output "file_path" {
  value       = local_file.welcome.filename
  description = "Path to the provisioned file"
}

terraform {
  required_version = ">= 1.6.0"
}

variable "server_config" {
  type = object({
    instance_type = string
    port          = number
    tags          = map(string)
    is_production = bool
  })
  default = {
    instance_type = "t3.micro"
    port          = 8080
    tags          = { Environment = "Dev", ManagedBy = "Terraform" }
    is_production = false
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Primary Provider
provider "aws" {
  region = "us-east-1"
}

# Multi-region Alias Provider
provider "aws" {
  alias  = "eu_west"
  region = "eu-west-1"
}

resource "local_file" "example" {
  filename = "${path.module}/sample.txt"
  content  = "Immutable infrastructure content"

  lifecycle {
    create_before_destroy = true
    prevent_destroy       = false
    ignore_changes        = []
  }
}

variable "db_password" {
  type        = string
  description = "Database master password"
  sensitive   = true

  validation {
    condition     = length(var.db_password) >= 8
    error_message = "The db_password must be at least 8 characters in length."
  }
}

locals {
  common_tags = {
    Project   = "Trak"
    ManagedBy = "Terraform"
  }
}

terraform {
  # Production Remote Backend with State Locking
  # backend "s3" {
  #   bucket         = "my-org-tfstate"
  #   key            = "prod/network/terraform.tfstate"
  #   region         = "us-east-1"
  #   dynamodb_table = "terraform-state-lock"
  #   encrypt        = true
  # }
}

# Query existing VPC without managing its lifecycle
# data "aws_vpc" "default" {
#   default = true
# }

locals {
  users = ["alice", "bob", "charlie"]

  # Transform list to map using for expression
  user_map = { for idx, u in local.users : u => idx }
}

locals {
  ingress_rules = [
    { port = 80,  description = "HTTP" },
    { port = 443, description = "HTTPS" }
  ]
}

